import{_ as e,o as a,c as o,a2 as s}from"./chunks/framework.BWuWLRhz.js";const g=JSON.parse('{"title":"即时答案与关键词功能","description":"","frontmatter":{},"headers":[],"relativePath":"zh-CN/user-guide/instant-answers.md","filePath":"zh-CN/user-guide/instant-answers.md","lastUpdated":1787480649000}'),d={name:"zh-CN/user-guide/instant-answers.md"};function r(n,t,c,i,l,h){return a(),o("div",null,[...t[0]||(t[0]=[s(`<h1 id="即时答案与关键词功能" tabindex="-1">即时答案与关键词功能 <a class="header-anchor" href="#即时答案与关键词功能" aria-label="Permalink to &quot;即时答案与关键词功能&quot;">​</a></h1><p>有些结果会在你打字的同时立刻出现，不需要等文件搜索完成——要么是始终生效的，要么是需要你先输入一个简短的关键词、再接你真正想查的内容(这样像&quot;搜索浏览器历史记录&quot;这类分量较重的功能，就不会在你打每一个跟它无关的字符时都来抢注意力)。大多数需要关键词的功能，其关键词都可以在<strong>设置 → 插件 → 配置</strong> 里自行修改。</p><h2 id="始终生效" tabindex="-1">始终生效 <a class="header-anchor" href="#始终生效" aria-label="Permalink to &quot;始终生效&quot;">​</a></h2><p>这些不需要关键词——只要你输入的内容匹配它们的模式，就会立刻触发。</p><h3 id="计算器" tabindex="-1">计算器 <a class="header-anchor" href="#计算器" aria-label="Permalink to &quot;计算器&quot;">​</a></h3><p>直接输入数学表达式，结果会实时显示出来，按 <strong>Enter</strong> 把结果复制到剪贴板:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>12 * (4 + 3)</span></span></code></pre></div><p>也支持显式的进制转换:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>255 to hex</span></span>
<span class="line"><span>0xFF to dec</span></span></code></pre></div><h3 id="环境变量" tabindex="-1">环境变量 <a class="header-anchor" href="#环境变量" aria-label="Permalink to &quot;环境变量&quot;">​</a></h3><ul><li><code>%NAME%</code> 展开某个具体的变量(包括像 <code>%PATH%</code> 这种多路径变量，会按路径逐条拆开列出)。</li><li><code>%partial</code> 模糊列出所有名称里包含 <code>partial</code> 的变量。</li></ul><h3 id="运行命令" tabindex="-1">运行命令 <a class="header-anchor" href="#运行命令" aria-label="Permalink to &quot;运行命令&quot;">​</a></h3><ul><li><code>#&lt;命令&gt;</code> 打开命令提示符窗口，<strong>以管理员权限</strong>运行 <code>&lt;命令&gt;</code>。</li><li><code>$&lt;命令&gt;</code> 打开命令提示符窗口，以普通权限运行 <code>&lt;命令&gt;</code>。</li></ul><h3 id="裸网址" tabindex="-1">裸网址 <a class="header-anchor" href="#裸网址" aria-label="Permalink to &quot;裸网址&quot;">​</a></h3><p>直接输入或粘贴一个 <code>http://</code>/<code>https://</code> 地址，Lertaro 会提示直接打开它。</p><h2 id="关键词触发-内置插件-前缀可配置" tabindex="-1">关键词触发(内置插件，前缀可配置) <a class="header-anchor" href="#关键词触发-内置插件-前缀可配置" aria-label="Permalink to &quot;关键词触发(内置插件，前缀可配置)&quot;">​</a></h2><p>输入关键词、一个空格，然后接你真正的查询内容。每个关键词都有一个默认的简短前缀，如果它和你常打的内容冲突，也可以在对应插件自己的<strong>配置</strong>对话框里单独修改。</p><table tabindex="0"><thead><tr><th>关键词(默认)</th><th>插件</th><th>搜索的内容</th></tr></thead><tbody><tr><td><code>ps</code></td><td>进程管理</td><td>按名称、PID 或窗口标题搜索正在运行的进程(也支持模糊/拼音匹配)——选中一个即可结束它。</td></tr><tr><td><code>win</code></td><td>窗口切换器</td><td>当前打开的、可切换的窗口(和 Alt+Tab 显示的是同一批)，按标题、进程名或 PID 搜索——选中即可切换到该窗口。</td></tr><tr><td><code>bm</code></td><td>浏览器数据</td><td>搜索你在该插件设置里添加的 Chrome/Chromium 系和 Firefox 系浏览器配置文件里的书签与历史记录。</td></tr><tr><td><code>set</code></td><td>核心扩展</td><td>应用内的每一项设置，按名称模糊匹配——选中一项即可直接跳转到设置里对应的那一行并高亮。只打 <code>set</code> 不加任何内容会列出所有设置。</td></tr><tr><td><code>flow</code></td><td>Flow 插件桥接</td><td>列出所有已加载的 Flow.Launcher 插件及其触发词（后面加空格可模糊过滤插件）。插件配置直接在<strong>设置 → 插件</strong>中统一管理。</td></tr></tbody></table><p>窗口切换器默认会把每个窗口实际内容的实时缩略图作为图标——截图在后台进行，不会拖慢输入速度：先立即显示程序图标，缩略图准备好之后再补上。在<strong>设置 → 插件 → 窗口切换器 → 配置</strong>里关掉&quot;用窗口内容作为图标&quot;就能完全跳过这部分截图，始终用程序图标。真正的独占全屏窗口(大多数游戏默认用的其实是无边框窗口化，这种没问题)截不到内容，会自动回退到程序图标。</p><p>浏览器数据插件的书签和历史记录是各自独立索引的——<strong>索引书签</strong>和<strong>索引历史记录</strong>是<strong>设置 → 插件 → 浏览器数据 → 配置</strong>里两个独立的开关，所以你可以只关掉历史记录(它通常比书签多得多)而继续搜索书签，反过来也一样。</p><h2 id="网页搜索" tabindex="-1">网页搜索 <a class="header-anchor" href="#网页搜索" aria-label="Permalink to &quot;网页搜索&quot;">​</a></h2><p>网页搜索插件自带了几个引擎/网站的默认关键词——<code>bd</code>(百度)、<code>g</code>(谷歌)、<code>bing</code>(必应)、<code>gh</code> (GitHub)、<code>wiki</code>(维基百科)、<code>yt</code>(YouTube)——你也可以在<strong>设置 → 插件 → 网页搜索 → 配置</strong>里完全自由地新增、编辑或删除条目，每一条都有自己的名称、关键词、图标和网址模板。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>g lertaro github</span></span></code></pre></div><p>会在浏览器里打开一次&quot;lertaro github&quot;的谷歌搜索。</p><h2 id="翻译" tabindex="-1">翻译 <a class="header-anchor" href="#翻译" aria-label="Permalink to &quot;翻译&quot;">​</a></h2><p>翻译插件的默认触发词是<code>tr</code>。在它后面输入文本，就会翻译成当前 Lertaro 界面所选的语言：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>tr hello</span></span></code></pre></div><p>结果会异步显示；按<strong>回车</strong>或单击即可复制。待翻译文本会发送到 Microsoft Translator，因此需要联网；目标语言始终是 App 当前设置的界面语言。可在<strong>设置 → 插件 → 翻译 → 配置</strong>中更改触发词。</p><h2 id="文件过滤器" tabindex="-1">文件过滤器 <a class="header-anchor" href="#文件过滤器" aria-label="Permalink to &quot;文件过滤器&quot;">​</a></h2><p>在<strong>设置 → 插件 → 文件过滤器 → 配置</strong>里，为特定文件夹单独建立索引规则。每条规则都有自己的 <strong>监控文件夹列表</strong>(递归扫描)、一个<strong>匹配后缀</strong>字段(例如 <code>*.exe;*.lnk</code>——支持用 <code>;</code> 或 <code>,</code> 分隔多个模式，全部都会被匹配；默认的 <code>*</code> 匹配所有文件)，以及一个可选的<strong>过滤器名称</strong>，会显示在结果的描述里。子文件夹永远会被收录，不受匹配后缀影响——匹配后缀只过滤文件。</p><p>给规则加上<strong>触发关键字</strong>，可以把它的结果收在一个前缀关键词后面(和上面的内置关键词一样)，而不是始终混在通用索引结果里参与排序。</p><h2 id="完全自定义-关键词你说了算" tabindex="-1">完全自定义(关键词你说了算) <a class="header-anchor" href="#完全自定义-关键词你说了算" aria-label="Permalink to &quot;完全自定义(关键词你说了算)&quot;">​</a></h2><h3 id="自定义命令" tabindex="-1">自定义命令 <a class="header-anchor" href="#自定义命令" aria-label="Permalink to &quot;自定义命令&quot;">​</a></h3><p>定义你自己的 <code>&lt;关键词&gt; &lt;参数&gt;</code> 命令，用来启动一个外部程序，全部在<strong>设置 → 插件 → 自定义命令 → 配置</strong>里配置。命令的参数模板支持位置占位符(<code>%s1</code>、<code>%s2</code>……对应每个用空格分隔的参数)，以及一个 &quot;剩余全部内容&quot;占位符(<code>%s</code>，代表关键词之后你输入的所有内容)。</p><p>每条命令还有一个<strong>在快速导航中显示</strong>勾选框(默认关闭)——打开后，这条命令会额外作为一个条目出现在<a href="./hotkeys.html#快速导航鼠标">快速导航</a>菜单的根层级，不用打关键词也能点开执行。<strong>快速导航子菜单</strong> 字段可以把它归到某个具名子菜单下，而不是直接放根层级——用 <code>/</code> 可以嵌套多级(比如&quot;工具/网络&quot;代表两级子菜单);留空则保持在根层级。以这种方式执行时，命令会按配置好的参数原样运行，因为这里没有打字输入的参数内容可以代入 <code>%s1</code>/<code>%s</code>。</p><hr><p>本页提到的插件都不是必需的——每一个都可以在<a href="./settings/plugins.html">设置 → 插件</a>里单独禁用，如果你不想让它占用键盘输入的注意力;而<a href="./search-syntax.html">搜索语法</a>介绍的是另一套始终生效、用于文件/ 文件夹/应用程序搜索的模糊查询语言，和本页内容是两回事。</p>`,37)])])}const u=e(d,[["render",r]]);export{g as __pageData,u as default};
